package dev.emanoel.shopcore.cart;
import dev.emanoel.shopcore.exception.*; import dev.emanoel.shopcore.product.ProductRepository; import dev.emanoel.shopcore.user.UserRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service
public class CartService { private final CartRepository carts; private final UserRepository users; private final ProductRepository products; public CartService(CartRepository c,UserRepository u,ProductRepository p){carts=c;users=u;products=p;} public record AddItem(Long productId,Integer quantity){} public record Item(Long id,Long productId,String name,Integer quantity,BigDecimal unitPrice,BigDecimal subtotal){} public record View(List<Item> items,BigDecimal total){}
 @Transactional public View add(String email,AddItem r){if(r.quantity()==null||r.quantity()<1)throw new BusinessException("Quantity must be at least 1");var u=users.findByEmailIgnoreCase(email).orElseThrow();var p=products.findById(r.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found"));if(!p.isActive())throw new BusinessException("Product is inactive");Cart c=carts.findByUserEmailIgnoreCase(email).orElseGet(()->carts.save(new Cart(u)));var existing=c.getItems().stream().filter(i->i.getProduct().getId().equals(p.getId())).findFirst();if(existing.isPresent())existing.get().add(r.quantity());else c.getItems().add(new CartItem(c,p,r.quantity()));return view(c);} public View get(String email){return carts.findByUserEmailIgnoreCase(email).map(this::view).orElse(new View(List.of(),BigDecimal.ZERO));} @Transactional public void remove(String email,Long itemId){Cart c=carts.findByUserEmailIgnoreCase(email).orElseThrow(()->new ResourceNotFoundException("Cart not found"));boolean ok=c.getItems().removeIf(i->i.getId().equals(itemId));if(!ok)throw new ResourceNotFoundException("Cart item not found");} private View view(Cart c){var items=c.getItems().stream().map(i->new Item(i.getId(),i.getProduct().getId(),i.getProduct().getName(),i.getQuantity(),i.getProduct().getPrice(),i.getProduct().getPrice().multiply(BigDecimal.valueOf(i.getQuantity())))).toList();return new View(items,items.stream().map(Item::subtotal).reduce(BigDecimal.ZERO,BigDecimal::add));} }
